import Typography from "@mui/material/Typography";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import Box from "@mui/material/Box";
import IconButton from "@mui/material/IconButton";
import CustomDataGrid from "src/@core/components/data-grid";
import Chip from "@mui/material/Chip";
import { styled } from "@mui/material/styles";
import { MEDIA_URL } from "src/network/endpoints";
import moment from "moment";
import AddIcon from "@mui/icons-material/Add";
import { Button } from "@mui/material";

const TableITSolutions = ({
  rows,
  totalCount,
  setCurrentPage,
  currentPage,
  setPageSize,
  pageSize,
  loading,
  toggleEdit,
  toggleDelete,
  onCellClick,
}) => {
  const statusColors = {
    inactive: "#FFB400",
    active: "#66bb6a",
  };
  const CustomChip = styled(Chip)(({ label }) => ({
    backgroundColor: statusColors[label] || statusColors.default,
    textTransform: "capitalize",
    color: "#fff",
    width: "100px",
  }));

  return (
    <CustomDataGrid
      loading={loading}
      rowCount={totalCount}
      rows={rows}
      handleCellClick={onCellClick}
      columns={[
        {
          field: "title",
          minWidth: 500,
          flex: 1,
          sortable: false,
          headerName: "Title",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.title}>
              {row.title}
            </Typography>
          ),
        },

        {
          field: "Actions",
          flex: 0.2,
          minWidth: 230,
          sortable: false,
          headerName: "Actions",
          renderCell: ({ row }) => (
            <Box display="flex" alignItems="center" gap="10px">
              <IconButton
                size="small"
                color="primary"
                variant="outlined"
                onClick={(e) => {
                  e.stopPropagation();
                  toggleEdit(e, "edit", row);
                }}
              >
                <EditIcon />
              </IconButton>
              <IconButton
                size="small"
                color="secondary"
                onClick={(e) => {
                  e.stopPropagation();
                  toggleDelete(e, row);
                }}
              >
                <DeleteIcon />
              </IconButton>
              <Button size="small" variant="contained">
                View Details
              </Button>
            </Box>
          ),
        },
      ]}
      currentPage={currentPage}
      pageSize={pageSize}
      setCurrentPage={setCurrentPage}
      setPageSize={setPageSize}
    />
  );
};

export default TableITSolutions;
